-- O*NET-SOC occupational titles (U.S. Department of Labor, public domain).
-- level 1 = official occupation, 0 = reported/alternate title. Used for
-- desired-title suggestions and matching vocabulary. Titles stay free-entry:
-- this table suggests, it never restricts (PROJECT-BRIEF section 4).
CREATE TABLE IF NOT EXISTS taxonomy_titles (
  name TEXT NOT NULL,
  name_normalized TEXT PRIMARY KEY,
  soc_code TEXT,
  level INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_tax_titles_norm ON taxonomy_titles(name_normalized);
